[
  {
    "name": "Bahr al-Madhhab",
    "author": "Abu al-Mahasin Abdul Wahid al-Ruyani",
    "desc": "Ensiklopedi fiqih Syafi'i luas yang merangkum rincian mazhab dan pendapat para ashhab."
  },
  {
    "name": "Mukhtasar al-Buwaiti",
    "author": "Abu Ya'qub Yusuf bin Yahya al-Buwaiti",
    "desc": "Ringkasan fiqih Syafi'i paling awal karya murid utama Imam al-Syafi'i."
  },
  {
    "name": "Al-Tahdhib fi Fiqh al-Imam al-Syafi'i",
    "author": "Abu Muhammad al-Husain bin Mas'ud al-Baghawi",
    "desc": "Kitab fiqih Syafi'i sistematis karya penyusun Sharh al-Sunnah."
  },
  {
    "name": "Tuhfat al-Tullab Syarh Tahrir Tanqih al-Lubab",
    "author": "Zakariyya bin Muhammad al-Ansari",
    "desc": "Syarah atas ringkasan fiqih Syafi'i yang padat, aplikatif, dan populer di pesantren."
  },
  {
    "name": "Syarh al-Sittin Mas'alah",
    "author": "Ahmad bin Ahmad al-Ramli",
    "desc": "Penjelasan atas risalah dasar kewajiban ibadah dan fiqih harian."
  },
  {
    "name": "Is'ad al-Rafiq wa Bughyat al-Saddiq",
    "author": "Muhammad bin Salim bin Sa'id Babashil",
    "desc": "Syarah Sullamut Taufiq yang memadukan hukum fiqih, tasawuf, dan aqidah."
  },
  {
    "name": "Qut al-Habib al-Gharib",
    "author": "Muhammad Nawawi al-Bantani",
    "desc": "Hasyiyah atas Fathul Qarib yang memperjelas hukum ibadah dan muamalah."
  },
  {
    "name": "Ghayat al-Muna Syarh Safinat al-Naja",
    "author": "Muhammad bin Ali Ba'atiyah",
    "desc": "Syarah modern mendalam atas matan Safinatun Najah dalam fiqih ibadah."
  },
  {
    "name": "Umdat al-Muhtaj ila Kitab al-Minhaj",
    "author": "Sirajuddin Abu Hafs Umar bin al-Mulaqqin",
    "desc": "Syarah komprehensif Minhaj at-Talibin sebelum era Al-Haitami dan Al-Ramli."
  },
  {
    "name": "Al-Ibtihaj fi Syarh al-Minhaj",
    "author": "Taqi al-Din Ali bin Abdil Kafi al-Subki",
    "desc": "Syarah analitis atas Minhaj at-Talibin oleh ulama besar mazhab Syafi'i."
  },
  {
    "name": "Al-Kaukab al-Wahhaj Syarh Minhaj al-Talibin",
    "author": "Muhammad al-Amini al-Harari",
    "desc": "Syarah kontemporer Minhaj at-Talibin dengan dalil Al-Qur'an dan Hadis lengkap."
  },
  {
    "name": "Fath al-Samad Syarh Matn al-Zubad",
    "author": "Ahmad bin Syaikh Hijazi al-Fasni",
    "desc": "Syarah atas nadzam Matan al-Zubad yang membahas fiqih Syafi'i terperinci."
  },
  {
    "name": "Al-Tadhkirah fi al-Fiqh al-Syafi'i",
    "author": "Ibn al-Mulaqqin al-Syafi'i",
    "desc": "Matan ringkas fiqih Syafi'i yang mencakup bab ibadah hingga muamalah."
  },
  {
    "name": "Al-Ibanah 'an Furu' al-Diyanah",
    "author": "Abu al-Qasim Abdul Rahman bin al-Furan",
    "desc": "Rujukan fiqih Syafi'i klasik yang membahas cabang-cabang hukum ibadah."
  },
  {
    "name": "Al-Kafiyah fi al-Fiqh",
    "author": "Abu al-Ma'ali al-Juwaini (Imam al-Haramain)",
    "desc": "Karya fiqih Syafi'i yang berfokus pada metodologi penyimpulan hukum."
  },
  {
    "name": "Al-Fatawa al-Khaniyyah",
    "author": "Hasan bin Mansur al-Uzjandi (Qadi Khan)",
    "desc": "Himpunan fatwa hukum fiqih Hanafi terkemuka yang menjadi rujukan para mufti."
  },
  {
    "name": "Al-Muheit al-Burhani",
    "author": "Burhanuddin Ibn Mazah al-Bukhari",
    "desc": "Ensiklopedi fiqih Hanafi raksasa yang memuat masalah muamalah dan ibadah."
  },
  {
    "name": "Jami' al-Rumuz",
    "author": "Shams al-Din Muhammad al-Quhistani",
    "desc": "Syarah atas Mukhtasar al-Wiqayah dalam mazhab Hanafi secara mendalam."
  },
  {
    "name": "Al-Fatawa al-Tatariyyah",
    "author": "Al-Alim bin A'la al-Indrapati",
    "desc": "Kumpulan fatwa mazhab Hanafi terlengkap yang disusun atas

